class Fail extends Error {}
const fail = (n, reason) => { throw new Fail(`error: line ${n}: ${reason}`) }

const NAME = /^[A-Za-z0-9_.\/:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

function int(n, field, v, least) {
  if (!INT.test(v) || BigInt(v) < BigInt(least)) fail(n, `${field} must be an integer of at least ${least}`)
  return BigInt(v)
}

