  const lines = input.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let started = false
  let prev = null
  for (let i = 0; i < lines.length; i++) {
    const n = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const t = line.split(/\s+/)
    const d = t[0]
    if (d === 'bucket' || d === 'window' || d === 'route') {
      if (started) fail(n, 'declarations must come before the first event')
    }
    if (d === 'bucket') {
      if (t.length !== 5) fail(n, 'expected bucket <name> <capacity> <refill> <per>')
      if (!NAME.test(t[1])) fail(n, `invalid policy name ${t[1]}`)
      const capacity = int(n, 'capacity', t[2], 1)
      const refill = int(n, 'refill', t[3], 0)
      const per = int(n, 'per', t[4], 1)
      if (policies.has(t[1])) fail(n, `policy ${t[1]} is declared twice`)
      policies.set(t[1], { name: t[1], kind: 'bucket', capacity, refill, per, state: new Map() })
    } else if (d === 'window') {
      if (t.length !== 4) fail(n, 'expected window <name> <limit> <span>')
      if (!NAME.test(t[1])) fail(n, `invalid policy name ${t[1]}`)
      const limit = int(n, 'limit', t[2], 0)
      const span = int(n, 'span', t[3], 1)
      if (policies.has(t[1])) fail(n, `policy ${t[1]} is declared twice`)
      policies.set(t[1], { name: t[1], kind: 'window', limit, span, state: new Map() })
    } else if (d === 'route') {
      if (t.length < 3) fail(n, 'expected route <prefix> <policy>...')
      if (!NAME.test(t[1])) fail(n, `invalid route prefix ${t[1]}`)
      if (routes.has(t[1])) fail(n, `prefix ${t[1]} is routed twice`)
      const list = []
      for (const p of t.slice(2)) {
