        list.push(policies.get(p))
      }
      routes.set(t[1], list)
    } else if (d === 'event') {
      if (t.length !== 3) fail(n, 'expected event <tick> <key>')
      if (!NAME.test(t[2])) fail(n, `invalid key ${t[2]}`)
      const tick = int(n, 'tick', t[1], 0)
      if (prev !== null && tick < prev) fail(n, `tick ${tick} is before tick ${prev}`)
      prev = tick
      started = true
      events.push([tick, t[2]])
    } else {
      fail(n, `unknown directive ${d}`)
    }
  }
  return { routes, events }
