  let s = p.state.get(key)
  if (p.kind === 'bucket') {
    // tokens are stored scaled by `per`, so fractions stay exact
    if (!s) { s = { num: p.capacity * p.per, last: tick }; p.state.set(key, s) }
    s.num += p.refill * (tick - s.last)
    s.last = tick
    const cap = p.capacity * p.per
    if (s.num > cap) s.num = cap
  } else {
    if (!s) { s = []; p.state.set(key, s) }
    const cut = tick - p.span
    while (s.length && s[0] <= cut) s.shift()
  }
